INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (14, 'Jahitan double chainstitch tidak terbentuk dengan benar', 'Jahitan rantai dua jarum tidak terbentuk sempurna, tidak seragam, atau mudah terurai.', 'Pemasangan benang tidak benar, ketegangan benang tidak sesuai, atau posisi jarum dan mekanisme pembentuk chainstitch tidak tepat.', 'Periksa kembali jalur kedua benang, sesuaikan ketegangan, dan periksa posisi serta sinkronisasi jarum dengan mekanisme pembentuk chainstitch.', 'Matikan mesin sebelum memeriksa jarum atau mekanisme pembentuk jahitan.', 'Data spesifikasi JUKI MS-1190 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (14, 'Benang jarum sering putus', 'Salah satu atau kedua benang jarum sering putus saat menjahit.', 'Jarum tidak sesuai, pemasangan benang salah, tegangan terlalu tinggi, atau terdapat bagian yang kasar pada jalur benang.', 'Gunakan jarum sesuai spesifikasi, periksa threading kedua jarum, sesuaikan tegangan, dan periksa jalur benang dari bagian yang kasar.', 'Matikan mesin sebelum mengganti jarum atau memperbaiki jalur benang.', 'Data spesifikasi JUKI MS-1190 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (14, 'Jahitan loncat atau chainstitch tidak terkunci dengan baik', 'Sebagian jahitan tidak terbentuk atau rantai jahitan mudah terlepas.', 'Jarum bengkok atau tumpul, timing jarum dan mekanisme chainstitch tidak tepat, atau threading tidak sesuai.', 'Ganti jarum yang sesuai, periksa pemasangan kedua jarum, periksa sinkronisasi mekanisme pembentuk jahitan, dan ulangi threading.', 'Pastikan mesin berhenti total sebelum memeriksa jarum dan mekanisme jahitan.', 'Data spesifikasi JUKI MS-1190 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (14, 'Panjang jahitan tidak sesuai', 'Panjang stitch lebih pendek atau lebih panjang dari pengaturan 1,2–3,2 mm.', 'Pengaturan stitch adjustment berubah, mekanisme push-button locking tidak bekerja normal, atau mekanisme feed mengalami gangguan.', 'Periksa pengaturan panjang jahitan, pastikan mekanisme pengunci bekerja, dan periksa mekanisme feed.', 'Matikan mesin sebelum melakukan penyetelan mekanisme stitch adjustment.', 'Data spesifikasi JUKI MS-1190 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (14, 'Kain tidak bergerak stabil pada area feed-off-the-arm', 'Kain tersendat, tertarik, bergeser, atau hasil jahitan tidak seragam.', 'Mekanisme pemakanan kotor, tekanan presser foot tidak sesuai, atau material tidak diposisikan dengan benar pada area arm.', 'Bersihkan area mekanisme feed, periksa tekanan presser foot, dan pastikan kain masuk serta diposisikan dengan benar pada feed-off-the-arm.', 'Matikan mesin sebelum membersihkan atau memeriksa mekanisme pemakanan.', 'Data spesifikasi JUKI MS-1190 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (14, 'Jarum patah atau posisi kedua jarum tidak normal', 'Salah satu jarum bengkok, patah, atau posisi kedua jarum tidak sejajar.', 'Ukuran atau tipe jarum tidak sesuai, pemasangan tidak tepat, jarum membentur komponen mesin, atau posisi needle guard tidak benar.', 'Pasang jarum sesuai spesifikasi mesin, periksa posisi dan ketinggian kedua jarum, serta periksa kondisi needle guard.', 'Matikan mesin dan lepaskan sumber daya sebelum mengganti atau menyetel jarum.', 'Data spesifikasi JUKI MS-1190 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (14, 'Jahitan atau posisi jarum tidak sesuai needle gauge', 'Jarak antarjarum tidak sesuai sehingga hasil jahitan tidak sesuai kebutuhan.', 'Needle gauge tidak sesuai konfigurasi mesin atau komponen jarum tidak terpasang pada posisi yang benar.', 'Periksa konfigurasi needle gauge 3,2–6,4 mm dan pastikan komponen jarum sesuai dengan konfigurasi mesin.', 'Matikan mesin sebelum mengganti atau mengatur posisi jarum.', 'Data spesifikasi JUKI MS-1190 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (14, 'Pelumasan atau gerakan mesin tidak normal', 'Gerakan mesin terasa berat, muncul suara tidak normal, atau bagian mekanis kurang lancar.', 'Pelumasan semi-otomatis tidak mencukupi, level atau jenis oli tidak sesuai, atau terdapat kotoran pada mekanisme.', 'Periksa sistem pelumasan semi-otomatis, gunakan JUKI New Defrix Oil No.1 atau oli setara ISO VG7 sesuai prosedur, dan bersihkan bagian mekanis yang kotor.', 'Matikan mesin sebelum memeriksa sistem pelumasan atau bagian mekanis yang bergerak.', 'Data spesifikasi JUKI MS-1190 dan panduan pemeriksaan umum');
